<script setup>
import {ref,onMounted,onUnmounted} from 'vue'
import {api} from '../lib/api'
import {useArcade} from '../stores/arcade'
const props=defineProps({game:String,sessionId:String,questionId:String,disabled:Boolean}),emit=defineEmits(['used']),s=useArcade(),open=ref(false),items=ref([]),busy=ref(false),error=ref(''),message=ref('');let pending=null,alive=true
async function load(){try{const result=await api('/game-items');if(alive)items.value=result.filter(i=>i.game===props.game)}catch(e){error.value=e.message}}
async function act(item,kind){if(busy.value)return;busy.value=true;error.value='';const signature=JSON.stringify([item.id,kind,props.sessionId,props.questionId]);if(pending?.signature!==signature)pending={signature,key:crypto.randomUUID()};try{const result=await api('/game-items/'+kind,{method:'POST',body:{item:item.id,requestKey:pending.key,sessionId:props.sessionId,questionId:props.questionId}});pending=null;if(!alive)return;if(signature!==JSON.stringify([item.id,kind,props.sessionId,props.questionId])){await load();return}if(kind==='use'){emit('used',{...result,item:item.id});message.value='아이템을 사용했어요.';open.value=false}else message.value=item.name+' 1개를 구매했어요.';await Promise.all([load(),s.refresh()])}catch(e){if(alive)error.value=e.message;if(e.status&&e.status<500)pending=null}finally{if(alive)busy.value=false}}
onMounted(load);onUnmounted(()=>alive=false)
</script>
<template><div class="game-item-shop"><button type="button" class="light" :aria-expanded="open" @click="open=!open">🎒 게임 아이템</button><section v-if="open" class="game-item-panel" aria-label="게임 아이템 상점"><div class="item-shop-title"><h3>아이템 상점 · 내 가방</h3><button type="button" class="light" @click="open=false">닫기</button></div><p>보유 {{s.data.coins.toLocaleString()}}P · 구매한 아이템은 게임을 나가도 보관돼요.</p><article v-for="item in items" :key="item.id"><div><b>{{item.name}}</b><small>{{item.description}}</small><span>내 가방 {{item.quantity}}개</span></div><button :disabled="busy||s.data.coins<item.price" @click="act(item,'buy')">{{item.price}}P 구매</button><button class="light" :disabled="busy||disabled||!sessionId||!item.quantity" @click="act(item,'use')">사용</button></article><p v-if="error" role="alert">{{error}}</p><p v-else-if="message" role="status">{{message}}</p></section></div></template>
<style scoped>.game-item-shop{position:relative;display:inline-block;max-width:100%}.game-item-panel{position:absolute;top:100%;left:0;right:auto;z-index:20;width:min(480px,calc(100vw - 54px));padding:18px;box-sizing:border-box;border:3px solid var(--rpg-edge);background:var(--rpg-paper,#fff);color:var(--rpg-ink);box-shadow:5px 6px var(--rpg-shadow);max-height:60dvh;overflow:auto}.item-shop-title{display:flex;align-items:center;justify-content:space-between;gap:10px}.item-shop-title h3{margin:0;font-size:16px}.game-item-panel p{font-size:11px;line-height:1.7}.game-item-panel article{display:flex;align-items:center;gap:8px;padding:14px 0;border-top:1px solid var(--rpg-mid)}.game-item-panel article>div{flex:1;min-width:0}.game-item-panel small,.game-item-panel span{display:block;font-size:10px;margin-top:6px}.game-item-panel button{font-size:11px;padding:9px;white-space:nowrap}@media(max-width:600px){.game-item-panel{position:fixed;top:20dvh;left:20px;right:20px;width:auto}.game-item-panel article{flex-wrap:wrap}.game-item-panel article>div{flex-basis:100%}}</style>
